// Aplatit les résultats Apify et attache le compte LinkedIn source (pour scraping/enrichissement uniquement,
// aucun message n'est envoyé sur ce compte dans cette campagne)
const items = $input.all();
const out = [];
for (const item of items) {
  const profiles = Array.isArray(item.json) ? item.json : [item.json];
  for (const p of profiles) {
    if (!p || !p.linkedinUrl) continue;
    out.push({ json: { ...p, sourceAccountName: 'Jean-Pierre Martin', sourceAccountId: 'B3R4_c4ZSIiSM0eNcajyew' } });
  }
}
return out;

// Scoring ICP artisans rénovation haut de gamme, sur 100 pts. Ne garde que score >= 55.
function scoreProfile(p) {
  const headline = (p.headline || p.summary || '').toLowerCase();
  const pos = (p.currentPosition && p.currentPosition[0]) || {};
  const posTitle = (pos.position || '').toLowerCase();
  const desc = (pos.description || '').toLowerCase();

  let s1 = 0;
  const isDecisionMaker = /g[ée]rant|fondateur|founder|dirigeant|artisan|chef d.entreprise|associ[ée]|architecte/.test(posTitle) || /g[ée]rant|fondateur|dirigeant|artisan/.test(headline);
  if (isDecisionMaker) s1 += 25;

  let s2 = 0;
  const renoKeywords = /r[ée]novation|second oeuvre|second œuvre|architecte d.int[ée]rieur|ma[ç]onnerie|menuiserie|plomberie|[ée]lectricit[ée]|d[ée]coration|am[ée]nagement/;
  if (renoKeywords.test(headline) || renoKeywords.test(desc)) s2 += 25;

  let s3 = 0;
  const hautDeGammeKeywords = /haut de gamme|luxe|premium|sur mesure|prestige|standing/;
  if (hautDeGammeKeywords.test(headline) || hautDeGammeKeywords.test(desc)) s3 += 20;

  let s4 = 0;
  if (p.followerCount && p.followerCount > 300) s4 += 10;
  if ((p.posts || []).length > 0) s4 += 20;

  const total = s1 + s2 + s3 + s4;
  return { total };
}

const items = $input.all();
const out = [];
for (const item of items) {
  const p = item.json;
  const score = scoreProfile(p);
  if (score.total < 55) continue;
  const pos = (p.currentPosition && p.currentPosition[0]) || {};
  out.push({
    json: {
      id: p.id,
      firstName: p.firstName || '',
      lastName: p.lastName || '',
      name: (p.firstName || '') + ' ' + (p.lastName || ''),
      linkedinUrl: p.linkedinUrl,
      publicIdentifier: (p.linkedinUrl || '').match(/linkedin\.com\/in\/([^/?]+)/)?.[1] || '',
      headline: p.headline || p.summary || '',
      company: pos.companyName || '',
      companyLinkedinUrl: pos.companyLinkedinUrl || '',
      dernierPostTexte: (p.posts && p.posts[0] && p.posts[0].text) || '',
      score: score.total,
      sourceAccountId: p.sourceAccountId
    }
  });
}
return out;

// Étape 1 (suite) : vérifie si Kaspr a retourné un mobile exploitable.
// Si oui -> on a le numéro, on saute l'étape 2 (site web).
// Si non -> on marque le lead pour tenter le fallback site web de l'entreprise.
const lead = $('Scorer ICP artisans (seuil >=55)').item.json;
const kaspr = $input.item.json;
const phoneRaw = kaspr.phone || kaspr.mobile || (kaspr.phones && kaspr.phones[0]) || null;

if (phoneRaw) {
  let phone = String(phoneRaw).replace(/[^\d+]/g, '');
  if (phone.startsWith('0')) phone = '+33' + phone.slice(1);
  if (!phone.startsWith('+')) phone = '+' + phone;
  return [{ json: { ...lead, phone, phoneSource: 'kaspr' } }];
}

// Pas de numéro Kaspr : on garde le lead pour la cascade fallback, sans phone.
return [{ json: { ...lead, phone: null, phoneSource: null } }];

// Extrait la première URL de résultat qui ressemble à un site d'entreprise (pas un annuaire/réseau social).
const html = $json.data || $json.body || '';
const lead = $('Vérifier résultat Kaspr').item.json;

const excludedDomains = /linkedin\.com|facebook\.com|pagesjaunes\.fr|societe\.com|instagram\.com|google\.com/;
const urlMatches = [...html.matchAll(/https?:\/\/[^"&\s]+/g)].map(m => m[0]);
const candidate = urlMatches.find(u => !excludedDomains.test(u));

if (!candidate) {
  return [{ json: { ...lead, companyWebsite: null } }];
}
return [{ json: { ...lead, companyWebsite: candidate } }];

// Extrait un numéro de téléphone français depuis le HTML brut de la page d'accueil.
// Cherche en priorité les formats explicites (tel:, 0X XX XX XX XX, +33...).
const lead = $('Extraire URL site web').item.json;
const html = $json.data || $json.body || '';

// Priorité 1 : lien tel: (le plus fiable, généralement affiché exprès par l'entreprise)
const telLinkMatch = html.match(/tel:([+\d\s().-]{8,20})/i);
// Priorité 2 : numéro français en texte brut (06/07 mobile en priorité, sinon fixe)
const mobileMatch = html.match(/0[67][\s.-]?\d{2}[\s.-]?\d{2}[\s.-]?\d{2}[\s.-]?\d{2}/);
const anyPhoneMatch = html.match(/0[1-9][\s.-]?\d{2}[\s.-]?\d{2}[\s.-]?\d{2}[\s.-]?\d{2}/);

const raw = (telLinkMatch && telLinkMatch[1]) || (mobileMatch && mobileMatch[0]) || (anyPhoneMatch && anyPhoneMatch[0]) || null;

if (!raw) {
  return [{ json: { ...lead, phone: null, phoneSource: null } }];
}

let phone = raw.replace(/[^\d+]/g, '');
if (phone.startsWith('0')) phone = '+33' + phone.slice(1);
if (!phone.startsWith('+')) phone = '+' + phone;

return [{ json: { ...lead, phone, phoneSource: 'site_web' } }];

// Point de fusion final : filtre définitivement tout lead sans numéro trouvé (ni Kaspr, ni site web).
const lead = $json;
if (!lead.phone) {
  return [];
}
return [{ json: lead }];

// Dedup contre les envois WhatsApp déjà effectués (état persistant du workflow) + cap quotidien progressif
const staticData = $getWorkflowStaticData('global');
staticData.sentIds = staticData.sentIds || {};
staticData.firstSendDate = staticData.firstSendDate || null;
const now = Date.now();
const SEVEN_DAYS = 7 * 24 * 3600000;
for (const id of Object.keys(staticData.sentIds)) {
  if (now - staticData.sentIds[id] > SEVEN_DAYS) delete staticData.sentIds[id];
}
const alreadySent = new Set(Object.keys(staticData.sentIds));

const items = $input.all();
const fresh = items.filter(i => !alreadySent.has(i.json.id));
fresh.sort((a, b) => (b.json.score || 0) - (a.json.score || 0));

// CAP PROGRESSIF: le numéro WhatsApp dédié est neuf, il doit "chauffer" avant d'atteindre le régime de
// croisière. Le cap du jour dépend du nombre de jours écoulés depuis le tout premier envoi (pas depuis
// le lancement du workflow), pour ne pas repartir à zéro si le workflow tourne sans avoir encore rien envoyé.
// Palier décidé : semaine 1 = 8/jour (départ direct à 8, pas de montée plus douce), puis 15, puis 25, puis 30-40 en plateau.
function dailyCapForDay(daysSinceFirstSend) {
  if (daysSinceFirstSend < 7) return 8;    // semaine 1
  if (daysSinceFirstSend < 14) return 15;  // semaine 2
  if (daysSinceFirstSend < 21) return 25;  // semaine 3
  return 35;                                // semaine 4+ : plateau cible (milieu de la fourchette 30-40)
}

if (!staticData.firstSendDate && fresh.length > 0) {
  staticData.firstSendDate = now;
}
const daysSinceFirstSend = staticData.firstSendDate ? Math.floor((now - staticData.firstSendDate) / (24 * 3600000)) : 0;
const DAILY_CAP = dailyCapForDay(daysSinceFirstSend);
const picked = fresh.slice(0, DAILY_CAP);

// Répartit les envois entre 9h et 18h Paris (horaires professionnels), avec jitter pour éviter un pattern régulier.
const parisNow = new Date(new Date().toLocaleString('en-US', { timeZone: 'Europe/Paris' }));
const endOfWindow = new Date(parisNow);
endOfWindow.setHours(18, 0, 0, 0);
const msRemaining = Math.max(endOfWindow.getTime() - parisNow.getTime(), 0);
const n = Math.max(picked.length, 1);
const baseIntervalMs = msRemaining / n;

let cursorMs = 0;
for (let idx = 0; idx < picked.length; idx++) {
  const jitterFactor = 0.8 + Math.random() * 0.4;
  cursorMs += baseIntervalMs * jitterFactor;
  picked[idx].json._waitSeconds = Math.min(Math.max(Math.round(cursorMs / 1000), 30), 32400);
}
if (picked.length) picked[0].json._runStartMs = Date.now();
for (let idx = 1; idx < picked.length; idx++) picked[idx].json._runStartMs = picked[0].json._runStartMs;

return picked;

// Calcule le délai restant à attendre pour respecter l'étalement prévu par le node précédent
const waitSeconds = $json._waitSeconds || 30;
const runStartMs = $json._runStartMs || Date.now();
const elapsedSeconds = (Date.now() - runStartMs) / 1000;
const remaining = Math.max(waitSeconds - elapsedSeconds, 5);
return [{ json: { ...$json, _remainingWaitSeconds: remaining } }];

// Génère le message WhatsApp personnalisé via Claude API.
// Charge le skill whatsapp-premier-message + business-info-artisans-renovation côté prompt.
const apiKey = $env.ANTHROPIC_API_KEY; // configuré en credential/variable n8n, jamais en dur
const lead = $json;

const systemPrompt = `Tu es Jean-Pierre Martin. Tu écris le tout premier message WhatsApp à un artisan/dirigeant d'entreprise de rénovation haut de gamme repéré sur LinkedIn.
Règles strictes (résumé du skill whatsapp-premier-message) :
- 2 à 4 phrases courtes maximum
- Justifie brièvement pourquoi tu écris sur WhatsApp (repéré son profil LinkedIn)
- Rebondis sur un élément CONCRET et réel fourni ci-dessous (jamais générique, jamais inventé)
- Termine par une question légère, jamais un pitch ni un lien
- Français impeccable, tous les accents, espace avant ? et !, pas de guillemets, pas de tiret cadratin
- Si aucun élément concret n'est fourni (pas de post, pas de spécialité claire), réponds EXACTEMENT: INSUFFICIENT_DATA`;

const userPrompt = `Prénom: ${lead.firstName}\nEntreprise: ${lead.company}\nHeadline LinkedIn: ${lead.headline}\nDernier post (si disponible): ${lead.dernierPostTexte || 'aucun'}\n\nGénère uniquement le message WhatsApp, rien d'autre.`;

const response = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://api.anthropic.com/v1/messages',
  headers: {
    'x-api-key': apiKey,
    'anthropic-version': '2023-06-01',
    'content-type': 'application/json'
  },
  body: {
    model: 'claude-sonnet-4-6',
    max_tokens: 300,
    system: systemPrompt,
    messages: [{ role: 'user', content: userPrompt }]
  },
  json: true
});

const text = response.content?.[0]?.text?.trim() || '';
if (!text || text === 'INSUFFICIENT_DATA') {
  return [];
}

return [{ json: { ...lead, whatsappMessage: text } }];

// Envoi WhatsApp via Unipile. WHATSAPP_ACCOUNT_ID doit être renseigné une fois le compte WhatsApp
// dédié connecté sur Unipile (cf. /api/v1/accounts, type WHATSAPP).
const key = $env.UNIPILE_API_KEY;
const base = 'https://api30.unipile.com:16068';
const whatsappAccountId = $env.UNIPILE_WHATSAPP_ACCOUNT_ID; // à définir après connexion du numéro dédié
const lead = $json;

if (!whatsappAccountId) {
  return [{ json: { ...lead, _sendSkippedReason: 'no_whatsapp_account_configured' } }];
}

const RETRYABLE_STATUS = [422, 429, 500];
const MAX_ATTEMPTS = 3;
let sent = false, lastError = null;

for (let attempt = 1; attempt <= MAX_ATTEMPTS && !sent; attempt++) {
  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: base + '/api/v1/chats',
      headers: { 'X-API-KEY': key, 'Content-Type': 'application/json' },
      body: {
        account_id: whatsappAccountId,
        attendees_ids: [lead.phone],
        text: lead.whatsappMessage
      },
      json: true
    });
    sent = true;
  } catch (e) {
    lastError = e;
    const status = e.response?.statusCode || e.statusCode || 0;
    if (!RETRYABLE_STATUS.includes(status) || attempt === MAX_ATTEMPTS) break;
    await new Promise(r => setTimeout(r, attempt === 1 ? 15000 : 45000));
  }
}

if (sent) {
  const staticData = $getWorkflowStaticData('global');
  staticData.sentIds = staticData.sentIds || {};
  staticData.sentIds[lead.id] = Date.now();
}

return [{ json: { ...lead, _sent: sent, _sendSkippedReason: sent ? null : ('error_' + (lastError?.response?.statusCode || 'unknown')) } }];
